import re
def find_adverb_position(text):
    ADS={"clearly","quickly","slowly","very","really"}
    for m in re.finditer(r'\S+', text):
        w=''.join(filter(str.isalpha,m.group())).lower()
        if w in ADS:return m.start(),m.start()+len(w),w
